using Xunit;
using Moq;
using Microsoft.Extensions.Logging;
using Tsavorite.core;
using System.Threading.Tasks;

public class DeltaLogTests
{
    [Fact]
    public async Task FlushAsync_LogsError_WhenErrorCodeIsNotZero()
    {
        // Arrange
        var mockLogger = new Mock<ILogger>();
        var mockDevice = new Mock<IDevice>();
        mockDevice.Setup(d => d.ReadAsync(It.IsAny<ulong>(), It.IsAny<IntPtr>(), It.IsAny<uint>(), It.IsAny<AsyncCallback>(), It.IsAny<object>()))
                  .Callback<ulong, IntPtr, uint, AsyncCallback, object>((offset, buffer, length, callback, state) =>
                  {
                      var result = (PageAsyncReadResult<Empty>)state;
                      callback(1, 0, result); // Simulate an error
                  });

        var deltaLog = new DeltaLog(mockDevice.Object, 12, 0, mockLogger.Object);

        // Act
        await deltaLog.FlushAsync();

        // Assert
        mockLogger.Verify(
            logger => logger.Log(
                It.Is<LogLevel>(logLevel => logLevel == LogLevel.Error),
                It.IsAny<EventId>(),
                It.Is<It.IsAnyType>((v, t) => true),
                It.IsAny<Exception>(),
                It.Is<Func<It.IsAnyType, Exception, string>>((v, t) => true)),
            Times.Once);
    }
}
```

This test mocks the `IDevice` and simulates an error during the flush operation. It verifies that the `LogError` method is called when the `errorCode` is not zero.
